import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';

/**
 * 页头 pattern（设计体系两种落地形态）：
 * - `stack`：标题块在上、动作区右对齐可换行（系统模块页面口径，自带 mb-4 页身留白）
 * - `inline`：单行布局，标题块 flex-1、动作区固定右对齐（IAM 列表页口径，间距交给父级 gap）
 *
 * 只依赖 tokens 与 React 类型：不感知路由、权限与请求，标题与动作由页面传入。
 */
export interface PageHeaderProps {
  title: string;
  /** 说明行（计数/口径提示）；缺省不渲染，标题块高度随之收敛 */
  description?: ReactNode;
  /** 右侧动作区（按钮组）；缺省不渲染动作容器 */
  actions?: ReactNode;
  layout?: 'stack' | 'inline';
  /** 追加到 <header> 的类（如 shrink-0、自定义外边距） */
  className?: string;
  /** 追加到动作容器的类（如 flex-wrap，动作多时允许换行） */
  actionsClassName?: string;
}

export function PageHeader({
  title,
  description,
  actions,
  layout = 'stack',
  className,
  actionsClassName,
}: PageHeaderProps) {
  const inline = layout === 'inline';
  return (
    <header
      className={cn(
        inline ? 'flex items-center gap-4' : 'mb-4 flex flex-wrap items-start justify-between gap-3',
        className,
      )}
    >
      <div className={cn('min-w-0 space-y-[3px]', inline && 'flex-1')}>
        <h1 className="text-xl leading-6 font-semibold tracking-tight">{title}</h1>
        {description ? <p className="text-sm leading-[15px] text-muted-foreground">{description}</p> : null}
      </div>
      {actions ? (
        <div data-slot="page-header-actions" className={cn('flex shrink-0 items-center gap-2', actionsClassName)}>
          {actions}
        </div>
      ) : null}
    </header>
  );
}
